// The managed disk parameters.
type ManagedDisk struct {
	// DiskEncryptionSet: Specifies the customer managed disk encryption set resource id for the managed disk. It can be set
	// only in UserSubscription mode.
	DiskEncryptionSet *DiskEncryptionSetParameters `json:"diskEncryptionSet,omitempty"`

	// SecurityProfile: Specifies the security profile settings for the managed disk. Note: It can only be set for Confidential
	// VMs and is required when using Confidential VMs.
	SecurityProfile *VMDiskSecurityProfile `json:"securityProfile,omitempty"`

	// StorageAccountType: The storage account type for use in creating data disks or OS disk.
	StorageAccountType *StorageAccountType `json:"storageAccountType,omitempty"`
}

// A network security group rule to apply to an inbound endpoint.
type NetworkSecurityGroupRule struct {
	// Access: The action that should be taken for a specified IP address, subnet range or tag.
	Access *NetworkSecurityGroupRuleAccess `json:"access,omitempty"`

	// Priority: Priorities within a pool must be unique and are evaluated in order of priority. The lower the number the
	// higher the priority. For example, rules could be specified with order numbers of 150, 250, and 350. The rule with the
	// order number of 150 takes precedence over the rule that has an order of 250. Allowed priorities are 150 to 4096. If any
	// reserved or duplicate values are provided the request fails with HTTP status code 400.
	Priority *int `json:"priority,omitempty"`

	// SourceAddressPrefix: Valid values are a single IP address (i.e. 10.10.10.10), IP subnet (i.e. 192.168.1.0/24), default
	// tag, or * (for all addresses).  If any other values are provided the request fails with HTTP status code 400.
	SourceAddressPrefix *string `json:"sourceAddressPrefix,omitempty"`

	// SourcePortRanges: Valid values are '*' (for all ports 0 - 65535) or arrays of ports or port ranges (i.e. 100-200). The
	// ports should in the range of 0 to 65535 and the port ranges or ports can't overlap. If any other values are provided the
	// request fails with HTTP status code 400. Default value will be *.
	SourcePortRanges []string `json:"sourcePortRanges,omitempty"`
}

